{
  "waba_id": "{{waba_id}}",
  "name": "police_yenileme_hatirlatma",
  "language": "tr",
  "category": "UTILITY",
  "allow_category_change": true,
  "components": [
    {
      "type": "BODY",
      "text": "Sayın {{1}}, {{2}} plakalı aracınızın poliçesi {{3}} tarihinde sona eriyor.",
      "example": {
        "body_text": [
          [
            "Ahmet Yılmaz",
            "34 ABC 123",
            "12.10.2026"
          ]
        ]
      }
    },
    {
      "type": "FOOTER",
      "text": "Mim Gökmen Sigorta"
    },
    {
      "type": "BUTTONS",
      "buttons": [
        {
          "type": "QUICK_REPLY",
          "text": "Teklif istiyorum"
        }
      ]
    }
  ]
}

{
  "waba_id": "{{waba_id}}",
  "name": "police_yenileme_hatirlatma_named",
  "language": "tr",
  "category": "UTILITY",
  "parameter_format": "NAMED",
  "components": [
    {
      "type": "HEADER",
      "format": "TEXT",
      "text": "Poliçe {{police_no}}",
      "example": {
        "header_text_named_params": [
          {
            "param_name": "police_no",
            "example": "TR-2026-001"
          }
        ]
      }
    },
    {
      "type": "BODY",
      "text": "Sayın {{ad_soyad}}, {{bitis_tarihi}} tarihinde biten poliçeniz için teklifiniz hazır.",
      "example": {
        "body_text_named_params": [
          {
            "param_name": "ad_soyad",
            "example": "Ayşe Yılmaz"
          },
          {
            "param_name": "bitis_tarihi",
            "example": "30.10.2026"
          }
        ]
      }
    },
    {
      "type": "FOOTER",
      "text": "Sorularınız için bize yazabilirsiniz"
    },
    {
      "type": "BUTTONS",
      "buttons": [
        {
          "type": "URL",
          "text": "Teklifi gör",
          "url": "https://ornek.com/teklif/{{1}}",
          "example": [
            "https://ornek.com/teklif/abc123"
          ]
        },
        {
          "type": "COPY_CODE",
          "example": "YENI2026"
        }
      ]
    }
  ]
}
